<?php
/** Modern CAPTCHA and ASP settings UI for WBCE. */
if (!function_exists('captcha_control_text')) {
    function captcha_control_text($text)
    {
        $decoded = html_entity_decode((string)$text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        return htmlentities($decoded, ENT_QUOTES | ENT_SUBSTITUTE | ENT_HTML5, 'UTF-8');
    }
}
