<script>
(function(){var app=document.getElementById('captcha-app');if(!app)return;var choices=app.querySelectorAll('input[name="captcha_type"]');function updateProvider(){var selected=app.querySelector('input[name="captcha_type"]:checked')||app.querySelector('input[name="captcha_type"]'),selectedId=selected?selected.value:'',hasSettings=false;app.querySelectorAll('.captcha-provider').forEach(function(card){card.classList.toggle('is-selected',card.contains(selected));});app.querySelectorAll('.captcha-provider-settings').forEach(function(panel){var visible=panel.getAttribute('data-provider')===selectedId;panel.hidden=!visible;if(visible)hasSettings=true;});var empty=app.querySelector('.captcha-provider-empty');if(empty)empty.hidden=hasSettings;}choices.forEach(function(choice){choice.addEventListener('change',updateProvider);});updateProvider();}());
</script>
